(x, y, t) => {
  const wx1 = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const wy1 = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const wx2 = Math.sin((x+wx1)*0.015+t*0.5)*8+Math.cos((y+wy1)*0.02-t*0.3)*6;
  const wy2 = Math.cos((y+wy1)*0.015-t*0.4)*8+Math.sin((x+wx1)*0.02+t*0.45)*6;
  const sx=x+wx1+wx2, sy=y+wy1+wy2;
  const src=[
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9],
    [80+Math.sin(t*0.7+3)*70,40+Math.cos(t*0.6+4)*50,0.11,2.1],
    [400+Math.cos(t*0.45+2)*80,200+Math.sin(t*0.65+1)*60,0.085,1.8]
  ];
  let aS=0,iS=0,aS2=0,cross=0;
  for(let j=0;j<src.length;j++){
    const[sX,sY,f,sp]=src[j];
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp);
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    aS2+=Math.cos(d*f*0.5-t*sp*1.3+0.8);
    for(let k=j+1;k<src.length;k++){
      const[sX2,sY2,f2,sp2]=src[k];
      const d2=Math.sqrt((sx-sX2)**2+(sy-sY2)**2);
      cross+=Math.sin((d-d2)*0.04+t*0.8)*0.15;
    }
  }
  const n=src.length;
  const act=aS/n,inh=iS/n,act2=aS2/n;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1)+Math.sin(sx*0.07+sy*0.06-t*1.5)*0.5+Math.sin(sx*0.12-sy*0.08+t*2)*0.25)/2.75;
  const ctrs=[[240,120],[140,60],[340,180],[100,180],[380,50]];
  let spiral=0;
  for(const[cX,cY]of ctrs){
    const d=Math.sqrt((sx-cX)**2+(sy-cY)**2);
    const a=Math.atan2(sy-cY,sx-cX);
    spiral+=(Math.sin(d*0.05-a*3-t*1.5)+Math.sin(d*0.04+a*4-t*1.2))*0.4;
  }
  spiral/=ctrs.length;
  const breath=1+Math.sin(t*0.4)*0.08;
  const rd=(act-inh*0.65+bg*0.25+spiral*0.8+act2*0.2+cross)*breath;
  const reaction=Math.tanh(rd*2.0);
  const cellBase=Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5;
  const cellDetail=Math.sin(sx*0.3+Math.sin(sy*0.2+t)*2)*Math.cos(sy*0.25+Math.sin(sx*0.15-t)*2)*0.3;
  const cell=Math.tanh((cellBase+cellDetail)*1.5)*0.25;
  const micro=Math.sin(sx*0.35+t*3)*Math.sin(sy*0.35-t*2.5)*0.06;
  const ridge=Math.sin(Math.sqrt((sx-240)**2+(sy-120)**2)*0.06-t*2)*Math.sin(Math.atan2(sy-120,sx-240)*2+t)*0.15;
  const blend=reaction*0.65+cell*0.18+micro+ridge;
  const v=blend*0.5+0.5;
  const pal=[
    [5,10,48],[10,35,78],[15,68,108],[22,115,125],
    [50,158,125],[110,185,95],[175,195,55],[215,165,45],
    [218,110,50],[195,58,55],[145,32,52],[75,18,45],[5,10,48]
  ];
  const idx=v*(pal.length-1);
  const i=Math.min(idx|0,pal.length-2);
  const f=idx-i;
  const sf=f*f*(3-2*f);
  const lum=0.88+Math.sin(reaction*Math.PI)*0.12;
  const edge=Math.abs(reaction)>0.6?1.1:(Math.abs(reaction)>0.25?1.03:0.96);
  const glow=Math.max(0,1-Math.abs(reaction))*0.06;
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*lum*edge+glow*50)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*lum*edge+glow*70)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*lum*edge+glow*90)|0)
  ];
}
